// get uploaded file
const item = $input.first();

// detect binary key
const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error("No binary data found on this item!");
}

const binaryKey = binaryKeys[0]; // take the first uploaded file
const fileName = item.binary[binaryKey].fileName;

// extract extension
const ext = fileName.split('.').pop().toLowerCase();

// map to type
let type;
if (ext === 'pdf') {
  type = 'PDF';
} else if (['docx', 'xlsx', 'csv', 'txt', 'html'].includes(ext)) {
  type = 'DOCUMENT';
} else if (['jpg','jpeg','png','tiff','bmp', 'avif'].includes(ext)) {
  type = 'IMAGE';
} else if (ext === 'pptx') {
  type = 'PPTX';
} else {
  type = 'UNKNOWN';
}

// return normalized data, include binary for next nodes
return [
  {
    json: {
      fileName,
      extension: ext,
      type
    },
    binary: {
      data: item.binary[binaryKey]
    }
  }
];

const item = $input.first();

// detect the first binary key
const binaryKey = Object.keys(item.binary || {})[0];
if (!binaryKey) throw new Error("No binary data found.");

// get the PDF as a proper Base64 string
const pdfBase64 = await this.helpers.getBinaryDataBuffer(0, binaryKey)
  .then(buffer => buffer.toString('base64'));

// return JSON
return [
  {
    json: {
      fileName: item.binary[binaryKey].fileName,
      type: 'PDF',
      base64: pdfBase64
    }
  }
];

